'<div style="max-width:680px;margin:auto;background:#fff;border-radius:12px;overflow:hidden;box-shadow:0 2px 16px rgba(0,0,0,.07)">' +

'<div style="background:linear-gradient(135deg,#1e3a5f,#2563eb);padding:28px 32px">' +
