'</div>' +

'<div style="display:flex;border-bottom:1px solid #f1f5f9">' +
'<div style="flex:1;padding:18px;text-align:center;border-right:1px solid #f1f5f9">' +
'<div style="font-size:30px;font-weight:800;color:#1e3a5f">' + leads.length + '</div>' +
