'<div style="flex:1;padding:18px;text-align:center;border-right:1px solid #f1f5f9">' +
'<div style="font-size:30px;font-weight:800;color:#92400e">' + medium + '</div>' +
'<div style="font-size:11px;color:#6b7280;margin-top:2px">MEDIUM</div>' +
'</div>' +
'<div style="flex:1;padding:18px;text-align:center">' +
