'<thead><tr style="background:#1e3a5f">' +
'<th style="padding:10px 12px;text-align:left;color:#fff">Business</th>' +
'<th style="padding:10px 12px;text-align:left;color:#fff">Phone</th>' +
'<th style="padding:10px 12px;text-align:left;color:#fff">Website</th>' +
'<th style="padding:10px 12px;text-align:center;color:#fff">Rating</th>' +
'<th style="padding:10px 12px;text-align:center;color:#fff">Score</th>' +
