'</tr></thead>' +
'<tbody>' + rows + '</tbody>' +
'</table>' +

'<div style="margin-top:18px;padding:14px;background:#f0fdf4;border-radius:8px;border-left:4px solid #22c55e;font-size:13px;color:#166534">' +
leads.length + ' new leads saved to Google Sheets | Full CSV attached' +
'</div>' +
'</div>' +

'<div style="background:#f8fafc;padding:14px 32px;border-top:1px solid #f1f5f9;text-align:center;font-size:11px;color:#9ca3af">' +
'Powered by n8n' +
'</div>' +
'</div>' +
'</body></html>';

return [{ json: { html: html, totalLeads: leads.length, keyword: keyword, location: location, date: date } }];

// Fix phone numbers to prevent formula errors
const items = $input.all();

items.forEach(item => {
  if (item.json.phone) {
    let phone = $input.first().json.phoneNumber;

    // Add single quote prefix to force text format
    // This prevents Sheets from interpreting as formula
    if (phone.startsWith('+') || phone.startsWith('=') || phone.startsWith('-')) {
      item.json.phone = "'" + phone;
    }
  }
});

return items;

// ============================================================
// IDENTIFY & BLOCK DUPLICATES — FINAL
// Reads lead data directly from Filter Valid Leads node
// Removes duplicates within the incoming batch
// Also checks against existing sheet data to avoid re-saving
// Passes ONLY unique new leads to the next node
// IF node after this checks: has leads? → Sheet, else → Stop
// ============================================================

const allLeads = $input.all();

// Safety check
if (!allLeads || allLeads.length === 0) {
  return [{ json: { 
    _noLeads: true, 
    message: 'No leads received from Filter node', 
    count: 0 
  }}];
}

// ── STEP 1: Read existing sheet data to avoid re-saving ──
let existingSheetRows = [];
try {
  existingSheetRows = $('Get row(s) in sheet').all();
} catch (e) {
  // Sheet empty or not executed yet — treat as first run
  existingSheetRows = [];
}

// ── STEP 2: Build lookup sets from EXISTING sheet data ──
const existingPhones    = new Set();
const existingEmails    = new Set();
const existingNames     = new Set();
const existingPlaceKeys = new Set();

for (const row of existingSheetRows) {
  const data = (row && row.json) ? row.json : {};

  const phone    = (data['Phone Number']  || '').toString().replace(/[^0-9]/g, '').toLowerCase().trim();
  const email    = (data['Email']          || '').toString().trim().toLowerCase();
  const name     = (data['Business Name']  || '').toString().trim().toLowerCase();
  const placeKey = (data['Place Key']      || '').toString().trim().toLowerCase();

  if (phone.length >= 7)                                       existingPhones.add(phone);
  if (email    && email    !== 'not found' && email    !== '') existingEmails.add(email);
  if (name     && name     !== 'n/a'       && name     !== '') existingNames.add(name);
  if (placeKey && placeKey !== 'n/a'       && placeKey !== '') existingPlaceKeys.add(placeKey);
}

// ── STEP 3: Also track duplicates WITHIN the incoming batch ──
// So if Apify returns same business twice, only first one passes
const batchPhones    = new Set();
const batchEmails    = new Set();
const batchNames     = new Set();
const batchPlaceKeys = new Set();

const uniqueLeads  = [];
const blockedLeads = [];

for (const item of allLeads) {
  const lead = (item && item.json) ? item.json : {};

  const phone    = (lead.phoneNumber  || '').toString().replace(/[^0-9]/g, '').toLowerCase().trim();
  const email    = (lead.email         || '').toString().trim().toLowerCase();
  const name     = (lead.businessName  || '').toString().trim().toLowerCase();
  const placeKey = (lead.placeKey      || '').toString().trim().toLowerCase();

  // Skip empty leads
  if (!name && !phone && !email && !placeKey) continue;

  // ── Check against EXISTING sheet data ──
  const dupInSheet =
    (phone.length >= 7            && existingPhones.has(phone))    ||
    (email    && email    !== 'not found' && existingEmails.has(email))   ||
    (name     && name     !== 'n/a'       && existingNames.has(name))     ||
    (placeKey && placeKey !== 'n/a'       && existingPlaceKeys.has(placeKey));

  // ── Check against CURRENT BATCH (avoid saving same lead twice) ──
  const dupInBatch =
    (phone.length >= 7            && batchPhones.has(phone))    ||
    (email    && email    !== 'not found' && batchEmails.has(email))   ||
    (name     && name     !== 'n/a'       && batchNames.has(name))     ||
    (placeKey && placeKey !== 'n/a'       && batchPlaceKeys.has(placeKey));

  if (dupInSheet || dupInBatch) {
    // Block this lead — it's a duplicate
    blockedLeads.push(lead.businessName || 'Unknown');
  } else {
    // Unique lead — passes through to Sheet node
    uniqueLeads.push({ json: { ...lead, isNew: true } });

    // Add to batch tracking sets
    if (phone.length >= 7)                                       batchPhones.add(phone);
    if (email    && email    !== 'not found' && email    !== '') batchEmails.add(email);
    if (name     && name     !== 'n/a'       && name     !== '') batchNames.add(name);
    if (placeKey && placeKey !== 'n/a'       && placeKey !== '') batchPlaceKeys.add(placeKey);
  }
}

// ── STEP 4: Return results ──

// No unique leads at all — everything was a duplicate
if (uniqueLeads.length === 0) {
  return [{ json: {
    _noLeads:      true,
    message:       'All ' + allLeads.length + ' leads were duplicates — nothing new to save',
    totalReceived: allLeads.length,
    blocked:       blockedLeads.length,
    passed:        0,
    blockedNames:  blockedLeads
  }}];
}

// Return only unique leads — these go to Sheet node
// Each item is a clean lead ready to be saved
return uniqueLeads;

const currentBatch = $input.item.json;

const batchNumber  = currentBatch.batchNumber  || 0;
const totalBatches = currentBatch.totalBatches || 0;
const rowNumbers   = currentBatch.rowNumbers   || [];
const batchSize    = rowNumbers.length;

if (!rowNumbers || rowNumbers.length === 0) {
  return {
    batchNumber,
    totalBatches,
    success:       false,
    message:       'Batch ' + batchNumber + ' is empty — skipped',
    rowNumbers:    [],
    readyToDelete: false
  };
}

return {
  batchNumber,
  totalBatches,
  batchSize,
  rowNumbers,
  success:       true,
  startIndex:    rowNumbers[0] - 1,
  endIndex:      rowNumbers[rowNumbers.length - 1] - 1,
  message:       'Batch ' + batchNumber + ' of ' + totalBatches + ' ready — deleting ' + batchSize + ' rows',
  readyToDelete: true
};
